nix eval --json --impure --expr '
let
  f = builtins.getFlake (toString ./.);
  hasEntire = packages: builtins.any (p: (p.pname or "") == "entire") packages;
in {
  personal-mac = hasEntire f.darwinConfigurations."Michaels-M1-Max".config.home-manager.users.michael.home.packages;
  work-mac = hasEntire f.darwinConfigurations."Michael-Holtzscher-Work".config.home-manager.users.michaelholtzcher.home.packages;
  nixos-desktop = hasEntire f.nixosConfigurations.nixos-desktop.config.home-manager.users.michael.home.packages;
  wanda = hasEntire f.homeConfigurations.wanda.config.home.packages;
}' | jq .

nix eval --json --impure --expr '
let
  f = builtins.getFlake (toString ./.);
  hasEntire = system:
    let
      pkgs = import f.inputs.nixpkgs { inherit system; config.allowUnfree = true; };
      packages = import ./modules/home-manager/packages.nix { inherit pkgs; inputs = f.inputs; };
    in builtins.any (p: (p.pname or "") == "entire") packages;
in {
  aarch64-darwin = hasEntire "aarch64-darwin";
  x86_64-linux = hasEntire "x86_64-linux";
}' | jq .
